class MergeWindowsContract(unittest.TestCase):
    def assertValueError(self, fn, *args):
        with self.assertRaises(ValueError):
            fn(*args)

    def test_identity(self):
        self.assertEqual(
            windows.merge_windows([]), []
        )
        self.assertEqual(
            windows.merge_windows([(0, 5), (10, 15)]),
            [(0, 5), (10, 15)],
        )
        self.assertEqual(
            windows.merge_windows([(0, 1440)]), [(0, 1440)]
        )

    def test_overlaps_and_touching_merge(self):
        self.assertEqual(
            windows.merge_windows([(0, 5), (4, 6)]), [(0, 6)]
        )
        self.assertEqual(
            windows.merge_windows([(0, 5), (5, 10)]), [(0, 10)]
        )
        self.assertEqual(
            windows.merge_windows([(0, 10), (5, 12), (12, 20), (30, 40)]),
            [(0, 20), (30, 40)],
        )

    def test_unsorted_input_sorted_output(self):
        self.assertEqual(
            windows.merge_windows([(10, 15), (0, 5)]),
            [(0, 5), (10, 15)],
        )

    def test_zero_length_dropped(self):
        self.assertEqual(windows.merge_windows([(5, 5)]), [])
        self.assertEqual(
            windows.merge_windows([(0, 5), (5, 5), (5, 10)]),
            [(0, 10)],
        )

    def test_generator_input(self):
        gen = ((i, i + 2) for i in range(0, 10, 4))
        self.assertEqual(
            windows.merge_windows(gen), [(0, 2), (4, 6), (8, 10)]
        )

    def test_does_not_mutate_input(self):
        original = [[0, 5], [4, 8]]
        copied = [list(pair) for pair in original]
        windows.merge_windows(original)
        self.assertEqual(original, copied)

    def test_invalid_pairs_raise(self):
        for bad in [
            [(5, 2)],
            [(-1, 5)],
            [(0, 1500)],
            [(0, 5, 6)],
            [(0, "5")],
            [("0", 5)],
            [(0, 5.0)],
            [None],
            [5],
            [(0, None)],
        ]:
            self.assertValueError(windows.merge_windows, bad)

    def test_non_iterable_raises(self):
        for bad in [None, 5, "x"]:
            self.assertValueError(windows.merge_windows, bad)


class FreeMinutesContract(unittest.TestCase):
    def assertValueError(self, fn, *args):
        with self.assertRaises(ValueError):
            fn(*args)

    def test_empty_iterable_full_day_free(self):
        self.assertEqual(
            planner.free_minutes([]),
            {"busy": [], "free": 1440},
        )
        self.assertEqual(
            planner.free_minutes(iter(())),
            {"busy": [], "free": 1440},
        )

    def test_simple_busy(self):
        self.assertEqual(
            planner.free_minutes(["09:00-10:00"]),
            {"busy": [(540, 600)], "free": 1380},
        )

    def test_overlap_and_touching_merge_with_free(self):
        self.assertEqual(
            planner.free_minutes(["08:00-09:00", "09:00-10:00", "09:30-11:00",
                                  "13:00-14:00"]),
            {"busy": [(480, 660)], "free": 1260},
        )

    def test_unsorted_input(self):
        self.assertEqual(
            planner.free_minutes(["13:00-14:00", "09:00-10:00"]),
            {"busy": [(540, 600), (780, 840)], "free": 1320},
        )

    def test_zero_length_busy_does_not_shrink_free(self):
        self.assertEqual(
            planner.free_minutes(["09:00-09:00"]),
            {"busy": [], "free": 1440},
        )

    def test_full_day_busy(self):
        self.assertEqual(
            planner.free_minutes(["00:00-24:00"]),
            {"busy": [(0, 1440)], "free": 0},
        )

    def test_free_is_sum_of_end_minus_start_of_merged(self):
        # Without merging, 08:00-10:00 and 10:00-12:00 are 240 busy minutes;
        # after merge the single window is also 240 minutes.
        self.assertEqual(
            planner.free_minutes(["08:00-10:00", "10:00-12:00"]),
            {"busy": [(480, 720)], "free": 1440 - 240},
        )

    def test_invalid_time_raises(self):
        self.assertValueError(planner.free_minutes, ["25:00-26:00"])
        self.assertValueError(planner.free_minutes, ["08:0"])

    def test_backwards_interval_raises(self):
        self.assertValueError(planner.free_minutes, ["10:00-09:00"])

    def test_extra_separator_raises(self):
        self.assertValueError(planner.free_minutes, ["09:00-10:00-11:00"])

    def test_no_separator_raises(self):
        self.assertValueError(planner.free_minutes, ["09:00"])

    def test_malformed_time_raises(self):
        self.assertValueError(planner.free_minutes, ["9:00-10:00"])

    def test_generator_input(self):
        gen = (s for s in ["09:00-10:00", "10:00-11:00"])
        self.assertEqual(
            planner.free_minutes(gen),
            {"busy": [(540, 660)], "free": 1320},
        )


